+			if fixture.fake.CallCount("notification.show") != 0 || fixture.fake.CallCount("workspace.report_metadata") != 0 {
+				t.Fatalf("Notice delivery attempted calls with no recorded workspace: %#v", fixture.fake.Calls)
+			}
+		})
+	}
+}
