package app

import (
	"context"
	"fmt"
	"regexp"
	"sort"
	"strconv"

	"github.com/thanhbinh1905/posse/internal/axi"
	"github.com/thanhbinh1905/posse/internal/herdr"
	"github.com/thanhbinh1905/posse/internal/store"
)

var taskPaneLabel = regexp.MustCompile(`^posse:([a-z0-9_-]+):t([1-9][0-9]*)$`)

func (s *Service) reconcileTaskPanes(ctx context.Context, db *store.DB, project store.Project, snapshot herdr.Snapshot) error {
	for _, pane := range snapshot.Panes {
		match := taskPaneLabel.FindStringSubmatch(pane.Label)
		if len(match) != 3 || match[1] != project.Name {
			continue
		}
		sequence, err := strconv.Atoi(match[2])
		if err != nil {
			continue
		}
		task, err := db.TaskStateBySeq(ctx, project.ID, sequence)
		if store.IsNotFound(err) {
			if err := createNoticeOnce(ctx, db, store.Notice{ProjectID: project.ID, Kind: "orphan_pane", Summary: "Unknown Task pane needs inspection", DataJSON: marshalJSON(map[string]any{"pane_label": pane.Label})}); err != nil {
				return err
			}
			continue
		}
		if err != nil {
			return err
		}
		if task.State != store.StateTornDown {
			continue
		}
		task, err = db.TaskByID(ctx, project.ID, task.ID)
		if err != nil {
			return err
		}
		if _, err := s.verifyTaskPanesGone(ctx, project, task); err != nil {
			if incompleteErr := s.recordTeardownIncomplete(ctx, db, project, task, err); incompleteErr != nil {
				return incompleteErr
			}
		}
	}
	return nil
}

func createNoticeOnce(ctx context.Context, db *store.DB, notice store.Notice) error {
	notices, err := db.Notices(ctx, notice.ProjectID, false)
	if err != nil {
		return err
	}
	for _, existing := range notices {
		if existing.Kind == notice.Kind && existing.TaskID == notice.TaskID && existing.Summary == notice.Summary {
			return nil
		}
	}
	_, err = db.CreateNotice(ctx, notice)
	return err
}

func (s *Service) pruneOrphanPanes(ctx *axi.Context, db *store.DB, project store.Project, apply bool) (axi.Object, error) {
	snapshot, err := s.snapshot(ctx.Context)
	if err != nil {
		return nil, err
	}
	sandboxes, err := db.Sandboxes(ctx.Context, project.ID)
	if err != nil {
		return nil, err
	}
	unknown := make(map[string][]herdr.Pane)
	for _, pane := range snapshot.Panes {
		match := taskPaneLabel.FindStringSubmatch(pane.Label)
		if len(match) != 3 || match[1] != project.Name {
			continue
		}
		sequence, err := strconv.Atoi(match[2])
		if err != nil {
			continue
		}
		if exists, err := db.TaskExistsBySeq(ctx.Context, project.ID, sequence); err != nil {
			return nil, err
		} else if exists {
			continue
		}
		if !ownsUnknownPane(snapshot, pane, project.Name, sequence, sandboxes) {
			continue
		}
		unknown[pane.Label] = append(unknown[pane.Label], pane)
	}
	labels := make([]string, 0, len(unknown))
	for label := range unknown {
		labels = append(labels, label)
	}
	sort.Strings(labels)
	type orphanRow struct {
		Label string   `json:"label"`
		Panes []string `json:"panes"`
	}
	rows := make([]orphanRow, 0)
	closed := []string{}
	for _, label := range labels {
		paneIDs := make([]string, 0, len(unknown[label]))
		for _, pane := range unknown[label] {
			paneIDs = append(paneIDs, pane.PaneID)
		}
		sort.Strings(paneIDs)
		rows = append(rows, orphanRow{Label: label, Panes: paneIDs})
	}
	result := func() axi.Object {
		return axi.Object{{Key: "project", Value: project.Name}, {Key: "orphan_panes", Value: rows}, {Key: "closed_panes", Value: closed}, {Key: "dry_run", Value: !apply}, {Key: "help", Value: []any{"Run `posse pool prune --yes` to close these orphan panes"}}}
