	sandboxes, err := db.Sandboxes(ctx.Context, project.ID)
	if err != nil {
		return nil, err
	}
	unknown := make(map[string][]herdr.Pane)
	for _, pane := range snapshot.Panes {
		match := taskPaneLabel.FindStringSubmatch(pane.Label)
		if len(match) != 3 || match[1] != project.Name {
			continue
		}
		sequence, err := strconv.Atoi(match[2])
		if err != nil {
			continue
		}
		if exists, err := db.TaskExistsBySeq(ctx.Context, project.ID, sequence); err != nil {
			return nil, err
		} else if exists {
			continue
		}
		if !ownsUnknownPane(snapshot, pane, project.Name, sequence, sandboxes) {
			continue
		}
		unknown[pane.Label] = append(unknown[pane.Label], pane)
	}
	labels := make([]string, 0, len(unknown))
	for label := range unknown {
		labels = append(labels, label)
	}
	sort.Strings(labels)
	type orphanRow struct {
		Label string   `json:"label"`
		Panes []string `json:"panes"`
	}
	rows := make([]orphanRow, 0)
	closed := []string{}
	for _, label := range labels {
